CREATE TABLE [dbo].[ccoLogDials](	  [logDial_id] INT NOT NULL IDENTITY(1,1)	, [callout_id] INT NOT NULL	, [cam_id] SMALLINT NOT NULL	, [tipoResDial_id] TINYINT NOT NULL	, [Telefono] VARCHAR(30) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [Puerto] SMALLINT NOT NULL	, [fecha] DATETIME NOT NULL DEFAULT(getdate())	, [tDialing] TINYINT NOT NULL DEFAULT((0))	, [tBusy] SMALLINT NOT NULL DEFAULT((0))	, [answerbit] BIT NULL	, [TipoDialingMode] VARCHAR(8) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [cal_id] INT NULL	, [tAnswerBit] DATETIME NULL	, [canceledNoAgents] BIT NULL	, [disconnectCause] VARCHAR(250) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL DEFAULT('')	, [cal_key] VARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL DEFAULT('')	, [call_TS] VARCHAR(15) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [tipoLlamada_id] SMALLINT NULL DEFAULT((0))	, CONSTRAINT [PK_ccoLogDials] PRIMARY KEY ([logDial_id] ASC))CREATE NONCLUSTERED INDEX [IX_ccoLogDials] ON [dbo].[ccoLogDials] ([fecha] ASC)CREATE NONCLUSTERED INDEX [IX_ccoLogDials_1] ON [dbo].[ccoLogDials] ([tipoResDial_id] ASC)CREATE NONCLUSTERED INDEX [IX_ccoLogDials_2] ON [dbo].[ccoLogDials] ([callout_id] ASC)CREATE NONCLUSTERED INDEX [IX_ccoLogDials_3] ON [dbo].[ccoLogDials] ([cam_id] ASC)CREATE NONCLUSTERED INDEX [IX_ccoLogDials_4] ON [dbo].[ccoLogDials] ([callout_id] DESC, [fecha] DESC)CREATE NONCLUSTERED INDEX [IX_ccoLogDials_5] ON [dbo].[ccoLogDials] ([cal_id] DESC)